#!/usr/bin/env python3
"""JSON 规范化器: 读 STDIN 整体 JSON, 输出去空白规范化文本; 非法则输出 ERR。

运行: echo '{"a":1}' | python3 solution.py
自检: python3 solution.py --selftest
"""
import sys


class ParseError(Exception):
    pass


class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def ws(self):
        while self.i < self.n and self.s[self.i] in " \t\n\r":
            self.i += 1

    def peek(self):
        return self.s[self.i] if self.i < self.n else ""

    def parse(self):
        self.ws()
        v = self.value()
        self.ws()
        if self.i != self.n:
            raise ParseError()
        return v

    def value(self):
        c = self.peek()
        if c == "":
            raise ParseError()
        if c == "{":
            return self.obj()
        if c == "[":
            return self.arr()
        if c == '"':
            return ("s", self.string())
        if c == "t":
            return self.lit("true", ("b", True))
        if c == "f":
            return self.lit("false", ("b", False))
        if c == "n":
            return self.lit("null", ("n", None))
        if c == "-" or c.isdigit():
            return ("i", self.number())
        raise ParseError()

    def lit(self, word, val):
        if self.s[self.i:self.i + len(word)] != word:
            raise ParseError()
        self.i += len(word)
        return val

    def number(self):
        start = self.i
        if self.peek() == "-":
            self.i += 1
        if self.peek() == "0":
            self.i += 1
            if self.i < self.n and self.s[self.i].isdigit():
                raise ParseError()  # 前导零
        elif self.peek() and self.s[self.i].isdigit():
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
        else:
            raise ParseError()
        if self.i < self.n and self.s[self.i] in ".eE":
            raise ParseError()  # 本任务仅支持整数
        return int(self.s[start:self.i])

    def string(self):
        self.i += 1  # skip "
        out = []
        while True:
            if self.i >= self.n:
                raise ParseError()
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return "".join(out)
            if c == "\\":
                self.i += 1
                if self.i >= self.n:
                    raise ParseError()
                e = self.s[self.i]
                if e == '"':
                    out.append('"')
                elif e == "\\":
                    out.append("\\")
                elif e == "/":
                    out.append("/")
                elif e == "n":
                    out.append("\n")
                elif e == "t":
                    out.append("\t")
                elif e == "u":
                    if self.i + 4 >= self.n:
                        raise ParseError()
                    h = self.s[self.i + 1:self.i + 5]
                    if len(h) != 4 or any(ch not in "0123456789abcdefABCDEF" for ch in h):
                        raise ParseError()
                    cp = int(h, 16)
                    if cp < 0x20:
                        raise ParseError()
                    out.append(chr(cp))
                    self.i += 4
                else:
                    raise ParseError()
                self.i += 1
            else:
                if ord(c) < 0x20:
                    raise ParseError()
                out.append(c)
                self.i += 1

    def arr(self):
        self.i += 1
        self.ws()
        items = []
        if self.peek() == "]":
            self.i += 1
            return ("a", items)
        while True:
            items.append(self.value())
            self.ws()
            c = self.peek()
            if c == ",":
                self.i += 1
                self.ws()
            elif c == "]":
                self.i += 1
                return ("a", items)
            else:
                raise ParseError()

    def obj(self):
        self.i += 1
        self.ws()
        pairs = {}
        if self.peek() == "}":
            self.i += 1
            return ("o", pairs)
        while True:
            if self.peek() != '"':
                raise ParseError()
            k = self.string()
            self.ws()
            if self.peek() != ":":
                raise ParseError()
            self.i += 1
            self.ws()
            pairs[k] = self.value()  # 重复键后者覆盖
            self.ws()
            c = self.peek()
            if c == ",":
                self.i += 1
                self.ws()
            elif c == "}":
                self.i += 1
                return ("o", pairs)
            else:
                raise ParseError()


def enc_string(s):
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def enc(v):
    t = v[0]
    if t == "n":
        return "null"
    if t == "b":
        return "true" if v[1] else "false"
    if t == "i":
        return str(v[1])
    if t == "s":
        return enc_string(v[1])
    if t == "a":
        return "[" + ",".join(enc(x) for x in v[1]) + "]"
    if t == "o":
        keys = sorted(v[1].keys(), key=lambda k: [ord(ch) for ch in k])
        return "{" + ",".join(enc_string(k) + ":" + enc(v[1][k]) for k in keys) + "}"
    raise ParseError()


def solve(text):
    try:
        return enc(Parser(text).parse())
    except (ParseError, RecursionError):
        return "ERR"


def selftest():
    cases = [
        ("-33", "-33"),
        ('["\\\\9\\u4e2d/",  null\n]', '["\\\\9中/",null]'),
        ("null", "null"),
        ("true", "true"),
        ("false", "false"),
        ("-0", "0"),
        ("0", "0"),
        ('"a\\"b\\\\c\\/d\\ne\\tf"', '"a\\"b\\\\c/d\\ne\\tf"'),
        ('{"b":1,"a":2}', '{"a":2,"b":1}'),
        ('{"a":1,"a":2}', '{"a":2}'),
        ("[1,2,3]", "[1,2,3]"),
        ("{}", "{}"),
        ("[]", "[]"),
        ("", "ERR"),
        ("   ", "ERR"),
        ("01", "ERR"),
        ("1.", "ERR"),
        ("-", "ERR"),
        ("1 2", "ERR"),
        ("[1,]", "ERR"),
        ('{"a":1,}', "ERR"),
        ("tru", "ERR"),
        ('"\\x"', "ERR"),
        ('"\\u001f"', "ERR"),
        ('"\\u000a"', "ERR"),
        ("[1 2]", "ERR"),
        ("{1:2}", "ERR"),
        ("[", "ERR"),
        ('"abc', "ERR"),
    ]
    fails = 0
    for inp, exp in cases:
        got = solve(inp)
        if got != exp:
            fails += 1
            print("FAIL inp=%r exp=%r got=%r" % (inp, exp, got))
    total = len(cases)
    print("PASS" if fails == 0 else "FAIL", fails, "/", total)
    return 0 if fails == 0 else 1


def main():
    if len(sys.argv) > 1 and sys.argv[1] == "--selftest":
        sys.exit(selftest())
    text = sys.stdin.read()
    if text == "":
        sys.stdout.write("ERR")
        sys.stdout.write("\n")
        return
    sys.stdout.write(solve(text))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
